if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();foreach($values as $k=>$v)$values[$k]=trim((string)($_POST[$k]??$v));$vehicleId=(int)($_POST['vehicle_id']??0);$s=$pdo->prepare('SELECT * FROM vehicles WHERE id=? AND status="active"');$s->execute([$vehicleId]);$vehicle=$s->fetch();if(!$vehicle)$errors[]='Выберите зарегистрированный автомобиль.';if(mb_strlen($values['title'])<3)$errors[]='Укажите название нарушения.';$amount=str_replace(',','.',$values['amount']);if(!is_numeric($amount)||(float)$amount<=0||(float)$amount>10000000)$errors[]='Сумма должна быть больше 0 и не превышать 10 000 000 ₽.';if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$values['due_date'])||strtotime($values['due_date'])===false||strtotime($values['due_date'])<strtotime(date('Y-m-d')))$errors[]='Укажите корректный срок оплаты не раньше сегодняшнего дня.';if(!$vehicle || !filter_var($vehicle['owner_email'],FILTER_VALIDATE_EMAIL))$errors[]='У автомобиля не задан корректный email владельца — банк не сможет найти плательщика.';
 if(!$errors){$ref='GIBDD-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(4)));try{$s=$pdo->prepare("INSERT INTO fines(vehicle_id,external_ref,title,amount,details,due_date,status,bank_status,issued_by,created_at) VALUES(?,?,?,?,?,?,'issued','pending',?,NOW())");$s->execute([$vehicleId,$ref,$values['title'],number_format((float)$amount,2,'.',''),$values['details']?:null,$values['due_date'],(int)current_user()['id']]);$fineId=(int)$pdo->lastInsertId();$s=$pdo->prepare('INSERT INTO vehicle_history(vehicle_id,event_type,title,description,event_date,created_by,created_at) VALUES(?,?,?,?,CURDATE(),?,NOW())');$s->execute([$vehicleId,'fine','Оформлено постановление '.$ref,$values['title'].' на сумму '.number_format((float)$amount,2,'.','').' ₽.',(int)current_user()['id']]);$result=dispatch_fine_to_bank($pdo,$config,$fineId);if($result['ok'])set_flash('success','Штраф создан и передан в «Капитал-Стандарт». Номер: '.$ref);else set_flash('warning','Штраф сохранён в реестре, но не подтверждена отправка в банк: '.$result['message'].' Можно повторить отправку из реестра штрафов.');redirect('fines.php');}catch(Throwable $e){$errors[]='Не удалось сохранить постановление. Проверьте подключение к базе данных.';}}
